    if src not in adj:
        raise KeyError(f"src '{src}' not in adjacency map")
    if dst not in adj:
        raise KeyError(f"dst '{dst}' not in adjacency map")

    # Priority queue stores (distance, num_hops, path)
    # This ensures that for equal distances, we prefer the path with fewer hops.
    # If hops are also equal, the path itself provides deterministic tie-breaking.
    pq = [(0, 1, [src])]
    # visited stores the minimum distance found to each node
    visited = {}

    while pq:
